import Foundation
import NetworkExtension

/**
 * PacketTunnelProvider (iOS NetworkExtension)
 *
 * This class is the direct Apple iOS counterpart to Android's `PeerLinkVpnService`.
 * It implements `NEPacketTunnelProvider` to create and manage the virtual network TUN interface on iOS.
 *
 * Lifecycle & Architecture:
 * 1. Invoked when the user initiates a connection from `VPNManager` via `startVPNTunnel()`.
 * 2. Configures virtual IP address (10.8.0.2 for client, 10.8.0.1 for host), default route, and DNS.
 * 3. `packetFlow.readPackets` reads raw IP packets generated by iOS apps.
 * 4. In a production deployment with a live relay server, packets are encrypted with ChaCha20-Poly1305
 *    and forwarded over a WebSockets/WebRTC DataChannel connection to the remote Host (Android or iOS).
 */
class PacketTunnelProvider: NEPacketTunnelProvider {

    private var currentRole: String = "client"
    private var currentHostId: String = ""
    private var isTunnelRunning: Bool = false

    override func startTunnel(options: [String : NSObject]?, completionHandler: @escaping (Error?) -> Void) {
        currentRole = (options?["role"] as? String) ?? "client"
        currentHostId = (options?["hostId"] as? String) ?? ""

        NSLog("PeerLink iOS: Starting PacketTunnelProvider in [\(currentRole)] mode for Host ID: \(currentHostId)")

        // Configure network settings
        let tunnelRemoteAddress = currentRole == "host" ? "10.8.0.2" : "10.8.0.1"
        let networkSettings = NEPacketTunnelNetworkSettings(tunnelRemoteAddress: tunnelRemoteAddress)
        networkSettings.mtu = 1500

        // IPv4 Configuration
        let virtualIp = currentRole == "host" ? "10.8.0.1" : "10.8.0.2"
        let ipv4Settings = NEIPv4Settings(addresses: [virtualIp], subnetMasks: ["255.255.255.0"])

        if currentRole == "client" {
            // Route all internet traffic through the PeerLink tunnel
            ipv4Settings.includedRoutes = [NEIPv4Route.default()]
            
            // Secure DNS settings
            let dnsSettings = NEDNSSettings(servers: ["1.1.1.1", "8.8.8.8"])
            dnsSettings.matchDomains = [""]
            networkSettings.dnsSettings = dnsSettings
        } else {
            // In host mode, route the virtual subnet
            let subnetRoute = NEIPv4Route(destinationAddress: "10.8.0.0", subnetMask: "255.255.255.0")
            ipv4Settings.includedRoutes = [subnetRoute]
        }

        networkSettings.ipv4Settings = ipv4Settings

        // Apply settings to iOS kernel
        setTunnelNetworkSettings(networkSettings) { [weak self] error in
            if let error = error {
                NSLog("PeerLink iOS: Failed to set tunnel network settings: \(error.localizedDescription)")
                completionHandler(error)
                return
            }

            self?.isTunnelRunning = true
            self?.startPacketRelayLoop()
            NSLog("PeerLink iOS: Virtual TUN interface active")
            completionHandler(nil)
        }
    }

    /**
     * =========================================================================
     * BACKEND RELAY SERVER API INTEGRATION POINT (iOS Swift):
     * =========================================================================
     * In a live cross-platform deployment connecting with remote Android or iOS peers:
     *
     * 1. Initialize Relay Socket (WebSocket / WebRTC DataChannel):
     *    let relaySocket = RelayClient(
     *        url: URL(string: "wss://relay.peerlink.network/v1/tunnel")!,
     *        hostId: self.currentHostId
     *    )
     *
     * 2. Outgoing Traffic (iOS Apps -> Remote Host):
     *    packetFlow.readPackets { [weak self] packets, protocols in
     *        for packet in packets {
     *            let encryptedPayload = ChaCha20Poly1305.encrypt(packet, key: sessionKey)
     *            relaySocket.send(encryptedPayload)
     *        }
     *    }
     *
     * 3. Incoming Traffic (Remote Host -> iOS Apps):
     *    relaySocket.onPacketReceived = { [weak self] encryptedData in
     *        let rawIpPacket = ChaCha20Poly1305.decrypt(encryptedData, key: sessionKey)
     *        self?.packetFlow.writePackets([rawIpPacket], withProtocols: [NSNumber(value: AF_INET)])
     *    }
     * =========================================================================
     */
    private func startPacketRelayLoop() {
        guard isTunnelRunning else { return }

        packetFlow.readPackets { [weak self] (packets: [Data], protocols: [NSNumber]) in
            guard let self = self, self.isTunnelRunning else { return }

            // In a full deployment, outbound packets are encrypted and forwarded to the relay
            // Continue the non-blocking read loop
            self.startPacketRelayLoop()
        }
    }

    override func stopTunnel(with reason: NEProviderStopReason, completionHandler: @escaping () -> Void) {
        NSLog("PeerLink iOS: Stopping PacketTunnelProvider, reason: \(reason.rawValue)")
        isTunnelRunning = false
        completionHandler()
    }

    override func handleAppMessage(_ messageData: Data, completionHandler: ((Data?) -> Void)?) {
        // Handle communication between main SwiftUI app and PacketTunnel extension
        completionHandler?(nil)
    }
}
